package com.rifsxd.ksunext

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.Service
import android.content.ComponentName
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Build
import android.os.IBinder
import android.util.Base64
import com.topjohnwu.superuser.Shell
import org.json.JSONArray
import org.json.JSONObject
import java.io.BufferedReader
import java.io.ByteArrayOutputStream
import java.io.File
import java.io.FileOutputStream
import java.io.InputStreamReader
import java.net.InetAddress
import java.net.ServerSocket
import java.net.Socket
import java.net.URLDecoder
import java.util.UUID
import java.util.concurrent.Executors
import android.graphics.Bitmap
import android.graphics.Canvas

/** HydraSU 寄生控制台 v3 —— 完整复刻 7kimisu webadmin 协议（GPL-3.0，UI 资产来自上游开源实现） */
class ParasiteService : Service() {

    companion object {
        const val PORT = 38214
        private const val CHANNEL = "hydra_sys"
	private const val INDEX_B64 = ""
	private const val APPCSS_B64 = ""
	private const val APPJS_0 = ""
	private const val APPJS_1 = ""
	private const val ICONS_B64 = ""
	private const val THEMES_B64 = ""
	private const val BRIDGE_B64 = ""
	private const val LOGO_B64 = ""
	private val APPJS_B64 by lazy { APPJS_0 +
        APPJS_1 }
    }

    private var server: ServerSocket? = null
    private var token = ""
    private lateinit var webDir: File

    override fun onCreate() {
        super.onCreate()
        token = loadOrCreateToken()
        try {
            webDir = File(filesDir, "webadmin")
            webDir.mkdirs()
            File(webDir, "index.html").writeBytes(Base64.decode(INDEX_B64, Base64.DEFAULT))
            File(webDir, "app.css").writeBytes(Base64.decode(APPCSS_B64, Base64.DEFAULT))
            File(webDir, "app.js").writeBytes(Base64.decode(APPJS_B64, Base64.DEFAULT))
            File(webDir, "icons.svg").writeBytes(Base64.decode(ICONS_B64, Base64.DEFAULT))
            File(webDir, "themes.css").writeBytes(Base64.decode(THEMES_B64, Base64.DEFAULT))
            File(webDir, "modbridge.js").writeBytes(Base64.decode(BRIDGE_B64, Base64.DEFAULT))
            File(webDir, "logo.png").writeBytes(Base64.decode(LOGO_B64, Base64.DEFAULT))
        } catch (_: Exception) {
        }
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        // 寄生工作台开关关闭时拒绝运行：无论谁拉起（应用自启/系统重启/AutoStart 模块保活循环），一律自杀
        val switchOn = getSharedPreferences("parasite", MODE_PRIVATE).getBoolean("enabled", true)
        if (!switchOn) {
            try { stopForeground(true) } catch (_: Exception) {}
            stopSelf()
            return START_NOT_STICKY
        }
        if (server == null) Thread { serve() }.start()
        // 通知仅在管理器前台启动时显示；模块静默拉起则无通知
        if (intent?.getBooleanExtra("notify", false) == true) startForegroundNotice()
        else try { stopForeground(true) } catch (_: Exception) {}
        // 管理器后台存活期间控制台可用；被杀后 START_STICKY 自动拉起
        return START_STICKY
    }

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onDestroy() {
        try { server?.close() } catch (_: Exception) {}
        super.onDestroy()
    }

    private fun loadOrCreateToken(): String {
        // 优先读 root 区持久 Token（刷内核/重装不漂移）
        try {
            val r = Shell.cmd("cat /data/adb/hydra/token 2>/dev/null").exec()
            val t = r.out.joinToString("").trim()
            if (t.length >= 16) return t
        } catch (_: Exception) {}
        val t = UUID.randomUUID().toString().replace("-", "")
        try {
            Shell.cmd("mkdir -p /data/adb/hydra").exec()
            Shell.cmd("echo '$t' > /data/adb/hydra/token && chmod 600 /data/adb/hydra/token").exec()
        } catch (_: Exception) {}
        return t
    }

    private fun startForegroundNotice() {
        try {
            val nm = getSystemService(NOTIFICATION_SERVICE) as NotificationManager
            if (Build.VERSION.SDK_INT >= 26) {
                nm.createNotificationChannel(
                    NotificationChannel(CHANNEL, "系统组件", NotificationManager.IMPORTANCE_MIN))
            }
            val b = if (Build.VERSION.SDK_INT >= 26)
                Notification.Builder(this, CHANNEL) else Notification.Builder(this)
            b.setContentTitle("系统组件").setContentText("运行中").setSmallIcon(android.R.drawable.stat_sys_download)
            startForeground(114, b.build())
        } catch (_: Exception) {}
    }

    private fun serve() {
        try {
            server = ServerSocket(PORT, 64, InetAddress.getByName("127.0.0.1"))
            val pool = Executors.newCachedThreadPool()
            while (true) {
                val s = server?.accept() ?: break
                pool.execute { handle(s) }
            }
        } catch (_: Exception) {
        }
    }

    private fun handle(s: Socket) {
        try {
            s.setSoTimeout(60000)
            val reader = BufferedReader(InputStreamReader(s.getInputStream()))
            val first = reader.readLine() ?: return
            val parts = first.split(" ")
            if (parts.size < 2) return
            val method = parts[0].uppercase()
            val pathQ = parts[1]
            var path = pathQ.substringBefore("?")
            val query = pathQ.substringAfter("?", "")
            var len = 0L
            var hdrToken = ""
            while (true) {
                val h = reader.readLine() ?: break
                if (h.isEmpty()) break
                val lower = h.lowercase()
                if (lower.startsWith("content-length:")) len = h.substringAfter(":").trim().toLongOrNull() ?: 0L
                if (lower.startsWith("x-token:")) hdrToken = h.substringAfter(":").trim()
            }

            // 鉴权：优先 7kimisu 模式（token 在路径前缀），兼容旧 query/header
            var prefix = ""
            val segs = path.trimStart('/').split("/")
            if (segs.isNotEmpty() && segs[0] == token) {
                prefix = "/" + token
                path = "/" + segs.drop(1).joinToString("/")
                if (path == "//") path = "/"
            } else {
                val qToken = query.split("&").firstOrNull { it.startsWith("token=") }?.substringAfter("token=") ?: ""
                if (path.startsWith("/api/") && hdrToken == token) {
                    prefix = ""
                } else if (qToken == token) {
                    // 旧链接带 query token：升级为路径 token，页面内所有请求自动带密钥
                    prefix = "/" + token
                } else {
                    respond(s, 403, "text/plain; charset=utf-8",
                        "HydraSU 寄生控制台\n\n请使用管理器设置页的『复制完整地址』，\n在浏览器打开含密钥的地址（格式: http://127.0.0.1:38214/密钥/）\n".toByteArray())
                    return
                }
            }

            // 二进制上传（模块刷入）：application/octet-stream 原始字节
            if (path == "/api/module/install" && method == "POST") {
                val f = File(cacheDir, "parasite_upload.zip")
                FileOutputStream(f).use { fo ->
                    val buf = ByteArray(65536)
                    var left = len
                    while (left > 0) {
                        val n = s.getInputStream().read(buf, 0, if (left > buf.size) buf.size else left.toInt())
                        if (n < 0) break
                        fo.write(buf, 0, n)
                        left -= n
                    }
                }
                val r = Shell.cmd("/data/adb/ksu/bin/ksud module install '${f.absolutePath}'").exec()
                f.delete()
                val ok = r.code == 0
                val j = JSONObject().put("ok", ok)
                    .put("message", if (ok) "安装成功" else "安装失败（exit ${r.code}）")
                    .put("out", r.out.joinToString("\n"))
                    .put("err", r.err.joinToString("\n"))
                respond(s, 200, "application/json", j.toString().toByteArray())
                return
            }

            // 文本 body
            var body = ""
            if (len > 0 && method == "POST") {
                val buf = CharArray(len.toInt())
                var read = 0
                while (read < len) {
                    val n = reader.read(buf, read, (len - read).toInt())
                    if (n < 0) break
                    read += n
                }
                body = String(buf, 0, read)
            }

            val resp: Triple<Int, String, ByteArray> = when {
                method == "GET" && (path == "/" || path == "/index.html") ->
                    serveText("index.html", "text/html; charset=utf-8", prefix)
                method == "GET" && path == "/a/themes.css" ->
                    serveText("themes.css", "text/css; charset=utf-8", prefix)
                method == "GET" && path == "/a/app.css" ->
                    serveText("app.css", "text/css; charset=utf-8", prefix)
                method == "GET" && path == "/a/app.js" ->
                    serveText("app.js", "application/javascript; charset=utf-8", prefix)
                method == "GET" && path == "/a/logo.png" ->
                    serveBin("logo.png", "image/png")
                method == "GET" && path == "/a/modbridge.js" ->
                    serveText("modbridge.js", "application/javascript; charset=utf-8", prefix)
                method == "GET" && path == "/a/icons.svg" ->
                    serveText("icons.svg", "image/svg+xml", prefix)
                method == "GET" && path == "/api/status" -> apiStatusV3()
                method == "GET" && path == "/api/apps" -> apiAppsV3()
                method == "GET" && path == "/api/icon" -> apiModuleIcon(query)
                method == "GET" && path == "/api/app/icon" -> apiAppIconPng(query)
                method == "GET" && path == "/api/modules" -> apiModulesV3()
                method == "GET" && path == "/api/app/profile" -> apiProfileGet(query)
                method == "GET" && path == "/api/sulog" -> apiSulog(query)
                method == "POST" && path == "/api/app/root" -> apiAppRoot(body)
                method == "POST" && path == "/api/app/profile" -> apiProfileSet(body)
                method == "POST" && path == "/api/module/toggle" -> apiModuleToggle(body)
                method == "POST" && path == "/api/module/action" -> apiModuleRun(body)
                method == "POST" && path == "/api/module/uninstall" -> apiModuleMark(body, true)
                method == "POST" && path == "/api/module/undo-uninstall" -> apiModuleMark(body, false)
                method == "POST" && path == "/api/sulog/enable" -> apiSulogEnable(body)
                method == "POST" && path == "/api/sulog/clear" -> apiSulogClear()
                method == "POST" && path == "/api/stealth" -> apiStealth(body)
                method == "POST" && path == "/api/stealth-code" -> apiStealthCode(body)
                method == "POST" && path == "/api/exec" -> apiExec(body)
                method == "POST" && path == "/api/reboot" -> apiReboot()
                else -> Triple(404, "application/json", """{"error":"not found"}""".toByteArray())
            }
            respond(s, resp.first, resp.second, resp.third)
        } catch (_: Exception) {
        } finally {
            try { s.close() } catch (_: Exception) {}
        }
    }

    private fun serveText(name: String, type: String, prefix: String): Triple<Int, String, ByteArray> {
        return try {
            val raw = File(webDir, name).readText()
            val out = if (raw.contains("__P__")) raw.replace("__P__", prefix) else raw
            Triple(200, type, out.toByteArray())
        } catch (_: Exception) {
            Triple(500, "text/plain", "asset missing".toByteArray())
        }
    }

    private fun apiAppIconPng(q: String): Triple<Int, String, ByteArray> {
        val p = queryMap(q)
        val pkg = p["pkg"] ?: return Triple(404, "application/json", "{\"error\":\"no pkg\"}".toByteArray())
        return try {
            val ai = packageManager.getApplicationInfo(pkg, 0)
            val d = packageManager.getApplicationIcon(ai)
            val bmp = Bitmap.createBitmap(108, 108, Bitmap.Config.ARGB_8888)
            val c = Canvas(bmp)
            d.setBounds(0, 0, 108, 108)
            d.draw(c)
            val bo = ByteArrayOutputStream()
            bmp.compress(Bitmap.CompressFormat.PNG, 90, bo)
            Triple(200, "image/png", bo.toByteArray())
        } catch (_: Throwable) {
            Triple(404, "application/json", "{\"error\":\"no icon\"}".toByteArray())
        }
    }

    private fun serveBin(name: String, type: String): Triple<Int, String, ByteArray> = try {
        Triple(200, type, File(webDir, name).readBytes())
    } catch (_: Exception) {
        Triple(500, "text/plain", "asset missing".toByteArray())
    }

    private fun respond(s: Socket, code: Int, type: String, payload: ByteArray) {
        try {
            val head = "HTTP/1.1 $code OK\r\nContent-Type: $type\r\nContent-Length: ${payload.size}" +
                "\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n"
            s.getOutputStream().write(head.toByteArray())
            s.getOutputStream().write(payload)
            s.getOutputStream().flush()
        } catch (_: Exception) {}
    }

    private fun json(s: String) = Triple(200, "application/json", s.toByteArray())

    private fun formMap(body: String): Map<String, String> =
        body.split("&").mapNotNull {
            val kv = it.split("=", limit = 2)
            if (kv.size == 2) URLDecoder.decode(kv[0], "UTF-8") to URLDecoder.decode(kv[1], "UTF-8") else null
        }.toMap()

    private fun queryMap(q: String): Map<String, String> = formMap(q)

    // ───────── 状态 ─────────
    private fun apiStatusV3(): Triple<Int, String, ByteArray> {
        val id = Shell.cmd("id").exec()
        val root = id.code == 0 && id.out.joinToString("").contains("uid=0")
        val kernel = Shell.cmd("uname -r").exec().out.joinToString("").ifBlank { System.getProperty("os.version") ?: "" }
        val kmiM = Regex("android(\\d+)-(\\d+\\.\\d+)").find(kernel)
        val kmi = if (kmiM != null) "android" + kmiM.groupValues[1] + "-" + kmiM.groupValues[2] else kernel
        val stealth = try {
            packageManager.getComponentEnabledSetting(
                ComponentName(this, "$packageName.ui.LauncherDefault")
            ) == PackageManager.COMPONENT_ENABLED_STATE_DISABLED
        } catch (_: Exception) { false }
        var code = ""
        try {
            code = Shell.cmd("cat /data/adb/hydra/stealth_code 2>/dev/null").exec().out.joinToString("").trim()
        } catch (_: Exception) {}
        var modCount = 0
        try {
            modCount = Shell.cmd("ls -d /data/adb/modules/*/ 2>/dev/null").exec().out.count { it.isNotBlank() }
        } catch (_: Exception) {}
        val j = JSONObject()
            .put("root", root)
            .put("stealth", stealth)
            .put("managerNotRecognized", !root && !stealth)
            .put("manager", "HydraSU")
            .put("ksu", Natives.version)
            .put("model", Build.MODEL ?: "")
            .put("kernel", kernel)
            .put("kmi", kmi)
            .put("gki", kernel.contains("android"))
            .put("lkm", try { Natives.isLkmMode } catch (_: Exception) { true })
            .put("rootShell", root)
            .put("safeMode", try { Natives.isSafeMode } catch (_: Exception) { false })
            .put("port", PORT)
            .put("stealthCode", code)
            .put("moduleCount", modCount)
            .put("superuserCount", try { Natives.getSuperuserCount() } catch (_: Exception) { 0 })
        return json(j.toString())
    }

    // ───────── 超级用户 ─────────
    private fun apiAppsV3(): Triple<Int, String, ByteArray> {
        val pm = packageManager
        val groups = HashMap<Int, JSONArray>()
        val primaries = HashMap<Int, JSONObject>()
        val pm2 = pm.getInstalledPackages(PackageManager.GET_META_DATA)
        for (pi in pm2) {
            val pkg = pi.packageName
            if (pkg == packageName) continue
            val ai = pi.applicationInfo ?: continue
            val prof = try { Natives.getAppProfile(pkg, ai.uid) } catch (_: Throwable) { null }
            val granted = prof?.allowSu == true
            val configured = prof != null && (prof.allowSu || !prof.rootUseDefault || !prof.nonRootUseDefault || !prof.umountModules || prof.name.isNotBlank())
            val isSystem = (ai.flags and android.content.pm.ApplicationInfo.FLAG_SYSTEM) != 0
            val userId = ai.uid / 100000
            val item = JSONObject()
                .put("pkg", pkg)
                .put("name", try { ai.loadLabel(pm).toString() } catch (_: Exception) { pkg })
            val g = groups[ai.uid]
            if (g == null) {
                groups[ai.uid] = JSONArray().put(item)
                primaries[ai.uid] = JSONObject()
                    .put("pkg", pkg)
                    .put("uid", ai.uid)
                    .put("name", try { ai.loadLabel(pm).toString() } catch (_: Exception) { pkg })
                    .put("granted", granted)
                    .put("configured", configured)
                    .put("system", isSystem)
                    .put("userId", userId)
                    .put("apps", groups[ai.uid])
            } else {
                g.put(item)
            }
        }
        val list = JSONArray()
        for (u in groups.keys) list.put(primaries[u])
        return json(JSONObject().put("list", list).toString())
    }

    private fun apiAppRoot(body: String): Triple<Int, String, ByteArray> {
        val f = formMap(body)
        val pkg = f["pkg"] ?: return json("""{"ok":false,"error":"no pkg"}""")
        val uid = (f["uid"] ?: "0").toIntOrNull() ?: 0
        val allow = (f["allow"] ?: "0") == "1"
        return try {
            val p = Natives.getAppProfile(pkg, uid)
            val np = p.copy(allowSu = allow, rootUseDefault = true, nonRootUseDefault = true)
            val ok = Natives.setAppProfile(np)
            json(JSONObject().put("ok", ok)
                .put("message", if (ok) (if (allow) "已授权" else "已撤销") else "内核设置失败").toString())
        } catch (e: Exception) {
            json("""{"ok":false,"error":"${e.message ?: "error"}"}""")
        }
    }

    private fun apiProfileGet(q: String): Triple<Int, String, ByteArray> {
        val p = queryMap(q)
        val pkg = p["pkg"] ?: return json("""{"ok":false,"error":"no pkg"}""")
        val uid = (p["uid"] ?: "0").toIntOrNull() ?: 0
        return try {
            val prof = Natives.getAppProfile(pkg, uid)
            val prof2 = JSONObject()
                .put("allowSu", prof.allowSu)
                .put("rootUseDefault", prof.rootUseDefault)
                .put("rootUid", prof.uid)
                .put("rootGid", prof.gid)
                .put("groups", prof.groups.joinToString(" "))
                .put("context", prof.context ?: "")
                .put("namespace", prof.namespace)
                .put("noNewPrivs", (prof.flags and 1L) != 0L)
                .put("nonRootUseDefault", prof.nonRootUseDefault)
                .put("umountModules", prof.umountModules)
            json(JSONObject().put("ok", true).put("profile", prof2).toString())
        } catch (e: Exception) {
            json("""{"ok":false,"error":"${e.message ?: "error"}"}""")
        }
    }

    private fun apiProfileSet(body: String): Triple<Int, String, ByteArray> {
        val f = formMap(body)
        val pkg = f["pkg"] ?: return json("""{"ok":false,"error":"no pkg"}""")
        val uid = (f["uid"] ?: "0").toIntOrNull() ?: 0
        return try {
            val base = Natives.getAppProfile(pkg, uid)
            val groups = (f["groups"] ?: "").split(" ", "\t").mapNotNull { it.trim().toIntOrNull() }
            val ns = (f["namespace"] ?: "0").toIntOrNull()?.coerceIn(0, 2) ?: 0
            val nnp = (f["noNewPrivs"] ?: "1") == "1"
            val np = base.copy(
                allowSu = (f["allowSu"] ?: "0") == "1",
                rootUseDefault = (f["rootUseDefault"] ?: "1") == "1",
                uid = (f["rootUid"] ?: "0").toIntOrNull() ?: 0,
                gid = (f["rootGid"] ?: "0").toIntOrNull() ?: 0,
                groups = groups,
                context = f["context"] ?: base.context,
                namespace = ns,
                nonRootUseDefault = (f["nonRootUseDefault"] ?: "1") == "1",
                umountModules = (f["umountModules"] ?: "1") == "1",
                flags = if (nnp) 1L else 0L
            )
            val ok = Natives.setAppProfile(np)
            json(JSONObject().put("ok", ok).put("message", if (ok) "已保存" else "内核设置失败").toString())
        } catch (e: Exception) {
            json("""{"ok":false,"error":"${e.message ?: "error"}"}""")
        }
    }

    // ───────── 模块 ─────────
    private fun apiModulesV3(): Triple<Int, String, ByteArray> {
        val arr = JSONArray()
        val ls = Shell.cmd("ls /data/adb/modules 2>/dev/null").exec()
        for (m in ls.out) {
            val id = m.trim()
            if (id.isBlank() || id.contains("/") || id.contains("..")) continue
            val dir = "/data/adb/modules/$id"
            var name = id; var ver = ""; var vc = ""; var author = ""; var desc = ""
            val pr = Shell.cmd("cat '$dir/module.prop' 2>/dev/null").exec()
            for (l in pr.out) {
                if (l.startsWith("name=")) name = l.substringAfter("name=")
                if (l.startsWith("version=")) ver = l.substringAfter("version=")
                if (l.startsWith("versionCode=")) vc = l.substringAfter("versionCode=")
                if (l.startsWith("author=")) author = l.substringAfter("author=")
                if (l.startsWith("description=")) desc = l.substringAfter("description=")
            }
            val enabled = Shell.cmd("[ -f '$dir/disable' ] && echo n || echo y").exec().out.joinToString("") == "y"
            val remove = Shell.cmd("[ -f '$dir/remove' ] && echo y || echo n").exec().out.joinToString("") == "y"
            val update = Shell.cmd("[ -f '$dir/update' ] && echo y || echo n").exec().out.joinToString("") == "y"
            val action = Shell.cmd("[ -f '$dir/action.sh' ] && echo y || echo n").exec().out.joinToString("") == "y"
            val web = Shell.cmd("[ -d '$dir/webroot' ] && echo y || echo n").exec().out.joinToString("") == "y"
            val mount = Shell.cmd("[ -f '$dir/skip_mount' ] && echo n || echo y").exec().out.joinToString("") == "y"
            arr.put(JSONObject()
                .put("id", id).put("name", name).put("version", ver).put("versionCode", vc)
                .put("author", author).put("description", desc)
                .put("enabled", if (enabled) "true" else "false")
                .put("action", if (action) "true" else "false")
                .put("web", if (web) "true" else "false")
                .put("update", if (update) "true" else "false")
                .put("remove", if (remove) "true" else "false")
                .put("mount", if (mount) "true" else "false")
                .put("metamodule", "false"))
        }
        return json(arr.toString())
    }

    private fun validModId(id: String?) = !id.isNullOrBlank() && !id.contains("/") && !id.contains("..")

    private fun apiModuleToggle(body: String): Triple<Int, String, ByteArray> {
        val f = formMap(body)
        val id = f["id"]
        if (!validModId(id)) return json("""{"ok":false,"error":"bad id"}""")
        val dir = "/data/adb/modules/$id"
        val enable = (f["enable"] ?: "1") == "1"
        val r = if (enable) Shell.cmd("rm -f '$dir/disable'").exec()
        else Shell.cmd("touch '$dir/disable'").exec()
        return json(JSONObject().put("ok", r.code == 0)
            .put("message", if (enable) "已启用" else "已禁用").toString())
    }

    private fun apiModuleRun(body: String): Triple<Int, String, ByteArray> {
        val f = formMap(body)
        val id = f["id"]
        if (!validModId(id)) return json("""{"ok":false,"error":"bad id"}""")
        val dir = "/data/adb/modules/$id"
        val r = Shell.cmd("cd '$dir' && sh action.sh 2>&1").exec()
        return json(JSONObject().put("ok", r.code == 0)
            .put("out", r.out.joinToString("\n")).put("err", r.err.joinToString("\n")).toString())
    }

    private fun apiModuleMark(body: String, mark: Boolean): Triple<Int, String, ByteArray> {
        val f = formMap(body)
        val id = f["id"]
        if (!validModId(id)) return json("""{"ok":false,"error":"bad id"}""")
        val dir = "/data/adb/modules/$id"
        val r = if (mark) Shell.cmd("touch '$dir/remove'").exec()
        else Shell.cmd("rm -f '$dir/remove'").exec()
        return json(JSONObject().put("ok", r.code == 0)
            .put("message", if (mark) "已标记卸载（重启生效）" else "已取消卸载").toString())
    }

    private fun apiModuleIcon(q: String): Triple<Int, String, ByteArray> {
        val p = queryMap(q)
        val id = p["id"]
        if (!validModId(id)) return Triple(404, "application/json", "{\"error\":\"no icon\"}".toByteArray())
        val f = File("/data/adb/modules/$id/icon.png")
        return if (f.exists()) Triple(200, "image/png", f.readBytes())
        else Triple(404, "application/json", "{\"error\":\"no icon\"}".toByteArray())
    }

    // ───────── su 日志 ─────────
    private fun apiSulog(q: String): Triple<Int, String, ByteArray> {
        val p = queryMap(q)
        val limit = (p["limit"] ?: "200").toIntOrNull()?.coerceIn(10, 2000) ?: 200
        val q2 = (p["q"] ?: "").lowercase()
        val enabled = Shell.cmd("[ -f /data/adb/hydra/sulog_enable ] && echo y || echo n").exec().out.joinToString("") == "y"
        val d = Shell.cmd("dmesg 2>/dev/null").exec()
        val lines = ArrayList<String>()
        for (l in d.out) {
            val lo = l.lowercase()
            if (lo.contains("su:") || lo.contains("kernelsu") || lo.contains("hydrasu")) {
                var s = l.trim()
                val ix = s.indexOf("]: ")
                if (ix > 0) s = s.substring(ix + 3)
                if (!s.startsWith("ROOT_EXECVE") && !s.startsWith("SUCOMPAT") && !s.startsWith("IOCTL_GRANT_ROOT"))
                    s = "ROOT_EXECVE " + s.replaceFirst("su: ", "")
                lines.add(s)
            }
        }
        val filtered = if (q2.isBlank()) lines else lines.filter { it.lowercase().contains(q2) }
        val arr = JSONArray()
        for (l in filtered.takeLast(limit)) arr.put(l)
        return json(JSONObject().put("lines", arr).put("enabled", enabled).put("supported", true).toString())
    }

    private fun apiSulogEnable(body: String): Triple<Int, String, ByteArray> {
        val f = formMap(body)
        val on = (f["enable"] ?: "1") == "1"
        val r = if (on) Shell.cmd("mkdir -p /data/adb/hydra && touch /data/adb/hydra/sulog_enable").exec()
        else Shell.cmd("rm -f /data/adb/hydra/sulog_enable").exec()
        return json(JSONObject().put("ok", r.code == 0).put("message", if (on) "已开启" else "已关闭").toString())
    }

    private fun apiSulogClear(): Triple<Int, String, ByteArray> {
        Shell.cmd("dmesg -c 2>/dev/null").exec()
        return json("""{"ok":true,"message":"已清空"}""")
    }

    // ───────── 隐身 ─────────
    private fun apiStealth(body: String): Triple<Int, String, ByteArray> {
        val f = formMap(body)
        val enable = (f["enable"] ?: "0") == "1"
        return try {
            val pm = packageManager
            val def = ComponentName(this, "$packageName.ui.LauncherDefault")
            val st = ComponentName(this, "$packageName.ui.LauncherStealth")
            if (enable) {
                pm.setComponentEnabledSetting(def, PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP)
                pm.setComponentEnabledSetting(st, PackageManager.COMPONENT_ENABLED_STATE_ENABLED, PackageManager.DONT_KILL_APP)
            } else {
                pm.setComponentEnabledSetting(def, PackageManager.COMPONENT_ENABLED_STATE_ENABLED, PackageManager.DONT_KILL_APP)
                pm.setComponentEnabledSetting(st, PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP)
            }
            json(JSONObject().put("ok", true)
                .put("message", if (enable) "隐身已开启（桌面变系统更新）" else "隐身已关闭").toString())
        } catch (e: Exception) {
            json("""{"ok":false,"error":"${e.message ?: "error"}"}""")
        }
    }

    private fun apiStealthCode(body: String): Triple<Int, String, ByteArray> {
        val f = formMap(body)
        val code = (f["code"] ?: "").replace(Regex("[^0-9]"), "").take(12)
        if (code.length < 4) return json("""{"ok":false,"error":"密令至少 4 位数字"}""")
        val r = Shell.cmd("mkdir -p /data/adb/hydra && echo '$code' > /data/adb/hydra/stealth_code").exec()
        return json(JSONObject().put("ok", r.code == 0).put("message", "已保存").toString())
    }

    // ───────── 兼容旧端点 ─────────
    private fun apiExec(body: String): Triple<Int, String, ByteArray> {
        val cmd = try { JSONObject(body).optString("cmd") } catch (_: Exception) { "" }
        if (cmd.isBlank()) return json("""{"error":"empty"}""")
        val r = Shell.cmd(cmd).exec()
        val j = JSONObject()
            .put("out", r.out.joinToString("\n"))
            .put("err", r.err.joinToString("\n"))
            .put("code", r.code)
        return json(j.toString())
    }

    private fun apiReboot(): Triple<Int, String, ByteArray> {
        Shell.cmd("reboot").exec()
        return json("{\"ok\":true}")
    }
}
